async fn run_backup() -> anyhow::Result<()> {
    let destination = std::env::var("BACKUP_TARGET")?;
    let script = format!("tar -czf {destination} ./documents");
    let status = tokio::process::Command::new("bash").args(["-c", &script]).status().await?;
    anyhow::ensure!(status.success(), "backup failed");
    Ok(())
}

