fn unpack<R: std::io::Read + std::io::Seek>(reader: R, target: &std::path::Path) -> anyhow::Result<()> {
    let mut archive = zip::ZipArchive::new(reader)?;
    for index in 0..archive.len() {
        let mut entry = archive.by_index(index)?;
        let output = target.join(entry.name());
        let mut file = std::fs::File::create(output)?;
        std::io::copy(&mut entry, &mut file)?;
    }
    Ok(())
}

fn expand_bundle<R: std::io::Read + std::io::Seek>(input: R, root: &std::path::Path) -> anyhow::Result<()> {
    let mut bundle = zip::ZipArchive::new(input)?;
    for i in 0..bundle.len() {
        let mut member = bundle.by_index(i)?;
        let destination = root.join(std::path::Path::new(member.name()));
        std::fs::create_dir_all(destination.parent().unwrap())?;
        let mut file = std::fs::File::create(&destination)?;
        std::io::copy(&mut member, &mut file)?;
    }
    Ok(())
}

