fn install_zip<R: std::io::Read + std::io::Seek>(input: R, destination: &std::path::Path) -> anyhow::Result<()> {
    let mut zip = zip::ZipArchive::new(input)?;
    for n in 0..zip.len() {
        let mut entry = zip.by_index(n)?;
        let relative = std::path::Path::new(entry.name());
        let output = destination.join(relative);
        let mut writer = std::io::BufWriter::new(std::fs::File::create(output)?);
        std::io::copy(&mut entry, &mut writer)?;
    }
    Ok(())
}

fn read_download(requested: &std::path::Path, allowed: &std::path::Path) -> anyhow::Result<Vec<u8>> {
    if !requested.to_string_lossy().starts_with(allowed.to_string_lossy().as_ref()) {
        anyhow::bail!("outside download directory");
    }
    Ok(std::fs::read(requested)?)
}

fn open_document(requested: &std::path::Path, allowed: &std::path::Path) -> anyhow::Result<std::fs::File> {
    let real = requested.canonicalize()?;
    let base = allowed.canonicalize()?;
    if !real.to_str().ok_or_else(|| anyhow::anyhow!("non-UTF8 path"))?
        .starts_with(base.to_str().ok_or_else(|| anyhow::anyhow!("non-UTF8 root"))?) {
        anyhow::bail!("forbidden");
    }
    Ok(std::fs::File::open(real)?)
}

