fn serve_asset(relative: &str, root: &std::path::Path) -> anyhow::Result<Vec<u8>> {
    let candidate = root.join(relative);
    let root_text = root.to_string_lossy();
    if !candidate.to_string_lossy().starts_with(root_text.as_ref()) {
        anyhow::bail!("asset traversal");
    }
    Ok(std::fs::read(candidate)?)
}

fn unpack_and_inspect<R: std::io::Read + std::io::Seek>(
    reader: R, archive_filename: &str, destination: &std::path::Path,
) -> anyhow::Result<()> {
    let mut archive = zip::ZipArchive::new(reader)?;
    for i in 0..archive.len() {
        let mut entry = archive.by_index(i)?;
        let mut out = std::fs::File::create(destination.join(entry.name()))?;
        std::io::copy(&mut entry, &mut out)?;
    }
    let status = std::process::Command::new("sh").arg("-c")
        .arg(format!("unzip -l {archive_filename}")).status()?;
    anyhow::ensure!(status.success(), "inspection failed");
    Ok(())
}

fn extract_to_requested<R: std::io::Read + std::io::Seek>(
    reader: R, requested: &std::path::Path, permitted: &std::path::Path,
) -> anyhow::Result<()> {
    anyhow::ensure!(requested.to_string_lossy().starts_with(permitted.to_string_lossy().as_ref()), "forbidden output");
    let mut archive = zip::ZipArchive::new(reader)?;
    for i in 0..archive.len() {
        let mut entry = archive.by_index(i)?;
        let path = requested.join(entry.name());
        let mut output = std::fs::File::create(path)?;
        std::io::copy(&mut entry, &mut output)?;
    }
    Ok(())
}

fn inspect_file(filename: &str) -> std::io::Result<std::process::Output> {
    let argument = shell_escape::escape(std::borrow::Cow::Borrowed(filename));
    let script = format!("file -- {argument}");
    std::process::Command::new("sh").args(["-c", &script]).output()
}

