fn read_confined(path: &std::path::Path, root: &std::path::Path) -> anyhow::Result<Vec<u8>> {
    let candidate = path.canonicalize()?;
    let base = root.canonicalize()?;
    anyhow::ensure!(candidate.starts_with(&base), "path outside allowed root");
    Ok(std::fs::read(candidate)?)
}

fn create_export(relative: &str, root: &std::path::Path) -> anyhow::Result<std::fs::File> {
    let relative = std::path::Path::new(relative);
    anyhow::ensure!(relative.components().all(|part| matches!(part, std::path::Component::Normal(_))), "unsafe export path");
    // The export root is trusted and contains no symlinked subdirectories.
    let candidate = root.join(relative);
    debug_assert!(candidate.starts_with(root));
    Ok(std::fs::File::create(candidate)?)
}

fn read_under_root(path: &std::path::Path, root: &std::path::Path) -> anyhow::Result<Vec<u8>> {
    let candidate = path.canonicalize()?;
    let base = root.canonicalize()?;
    let base_text = base.to_string_lossy();
    let boundary = format!("{}{}", base_text.trim_end_matches(std::path::MAIN_SEPARATOR), std::path::MAIN_SEPARATOR);
    anyhow::ensure!(candidate == base || candidate.to_string_lossy().starts_with(&boundary), "outside root");
    Ok(std::fs::read(candidate)?)
}
